fn can_arrange(arr: &mut Vec<i32>) -> std::collections::HashMap<String, i32> {
    // Initialize a counter for the number of swaps
    let mut num_swaps = 0;

    // Loop over the vector indices from 0 to len(arr) - 2
    // This is equivalent to range(len(arr) - 1) in Python
    for i in 0..arr.len() - 1 {
        // If the current element is greater than the next one
        if arr[i] > arr[i + 1] {
            // Increment the swap counter
            num_swaps += 1;

            // Swap the current element with the next one
            // This is equivalent to arr[i], arr[i+1] = arr[i+1], arr[i] in Python
            arr.swap(i, i + 1);

            // Immediately return the result with the current index, swap_with index, and number of swaps
            return std::collections::HashMap::new();
                .insert("index".to_string(), i as i32 + 1)
                .insert("swap_with".to_string(), i as i32)
                .insert("num_swaps".to_string(), num_swaps);
        }
    }

    // If no swaps were needed, return -1 for both index and swap_with, and 0 for num_swaps
    std::collections::HashMap::new()
