extension datastore: NSManagedObjectFactory {
    static func addHabit(_ habit: Habit) async -> Bool {
        let context = NSManagedObjectContext(concurrencyType: .main)
        context.perform {
            let entity = NSEntityDescription.entity(forEntityForIdentifier: "Habit", in: context)
            let newHabit = NSManagedObject(entity: entity, insertInto: context) as? Habit
            newHabit?.name = habit.name
            newHabit?.isCompleted = habit.isCompleted
